from ledger.posting import post_entry


class FakeLedger:

    def __init__(self):
        self.entries = {}
        self.appended = []

    def append(self, reference, amount_cents, clerk):
        self.appended.append((reference, amount_cents, clerk))
        self.entries.setdefault(reference, {"amount_cents": amount_cents})
        return reference


class FakeEntry:

    def __init__(self, reference, amount_cents):
        self.reference = reference
        self.amount_cents = amount_cents


def test_post_entry_appends_and_returns_reference():
    ledger = FakeLedger()
    entry = FakeEntry("TU-70118", 4800)
    assert post_entry(ledger, entry, "mharris") == "TU-70118"


def test_duplicate_reference_is_not_refused_yet():
    ledger = FakeLedger()
    first = FakeEntry("TU-70119", 3200)
    second = FakeEntry("TU-70119", 3200)
    post_entry(ledger, first, "mharris")
    post_entry(ledger, second, "mharris")
    assert len(ledger.appended) == 2
